#include "ToolbarImageCache.hpp"
#include <iostream>
using namespace udm;
static ToolbarBitmap icon(int value,int size=2){return {size,size,Bytes((size_t)size*size*4,(BYTE)value)};}
static ToolbarRasterSet raster(const ToolbarRasterKey& key,BYTE value){ToolbarRasterSet result;for(auto& image:result.pixels)for(auto& state:image)state=Bytes((size_t)key.width*key.height*4,value);return result;}
int wmain(int argc,wchar_t** argv){if(argc!=2)return 2;auto root=fs::absolute(argv[1]);if(fs::exists(root))return 2;fs::create_directories(root);Json checks=Json::array();std::string error;const auto check=[&](bool value,const char* name){checks.push_back({{"name",name},{"passed",value}});if(!value)throw std::runtime_error(name);};
 try{
  ToolbarSourceCache sources;int reads=0;auto loader=[&](int index){++reads;return icon(index+1);};auto first=sources.get(0,loader);auto repeated=sources.get(0,loader);check(reads==1&&first==repeated&&first->pixels==icon(1).pixels,"A hot decoded source is owned and does not invoke its loader again");
  for(int i=1;i<ToolbarCommandCount;++i)sources.get(i,loader);check(reads==12&&sources.entries()==12&&sources.bytes()==12*16,"Each of twelve source slots loads once");
  for(int index:{-1,ToolbarCommandCount}){bool rejected=false;try{sources.get(index,loader);}catch(...){rejected=true;}check(rejected&&reads==12,"An invalid icon index cannot invoke its loader");}
  const auto epoch=sources.generation();sources.clear();check(sources.entries()==0&&sources.bytes()==0&&sources.generation()==epoch+1,"Invalidation clears retained sources and advances their generation");check(first->pixels==icon(1).pixels,"An immutable borrower remains valid after cache invalidation");auto changed=sources.get(0,[&](int){++reads;return icon(77);});check(changed!=first&&changed->pixels==icon(77).pixels&&first->pixels==icon(1).pixels,"Reload publishes new pixels without changing an older borrower");
  ToolbarSourceCache independent;check(independent.entries()==0&&independent.generation()==0,"A second window starts with an independent cache");sources.clear();bool rejected=false;try{sources.get(0,[](int)->ToolbarBitmap{throw std::runtime_error("Owned source failure");});}catch(...){rejected=true;}check(rejected&&sources.entries()==0&&sources.bytes()==0,"A source-loader failure cannot poison a cache slot");
  for(int mode=0;mode<4;++mode){rejected=false;try{sources.get(0,[=](int){auto value=icon(1);if(mode==0)value.width=0;if(mode==1)value.height=-1;if(mode==2)value.width=257;if(mode==3)value.pixels.pop_back();return value;});}catch(...){rejected=true;}check(rejected&&sources.entries()==0,"Malformed decoded dimensions or pixels are rejected before retention");}
  check(sources.get(0,loader)!=nullptr,"A failed source slot can retry successfully");sources.clear();for(int i=0;i<ToolbarCommandCount;++i)sources.get(i,[](int){return icon(5,256);});check(sources.entries()==12&&sources.bytes()==3*1024*1024,"Decoded source retention is bounded to three MiB");
  ToolbarRasterKey a{2,2,false,0},b{2,2,true,0},c{2,2,false,1};check(!(a==b)&&!(a==c)&&!(a==ToolbarRasterKey{3,2,false,0})&&!(a==ToolbarRasterKey{2,3,false,0})&&a==ToolbarRasterKey{2,2,false,0},"Raster identity includes dimensions look and source generation");
  ToolbarRasterCache frames(2);int renders=0;auto build=[&](const ToolbarRasterKey& key){return frames.get(key,[&]{++renders;return raster(key,(BYTE)renders);});};auto fa=build(a),fb=build(b);check(renders==2&&frames.entries()==2&&frames.bytes()==1152,"Raster entries retain their complete normal hot and disabled pixels");check(build(a)==fa&&renders==2,"A hot raster lookup skips pixel generation and touches recency");auto fc=build(c);check(renders==3&&frames.entries()==2&&build(a)==fa&&renders==3,"Capacity eviction preserves the recently used raster");auto newb=build(b);check(newb!=fb&&renders==4&&fb->pixels[0][0][0]==2,"An evicted raster rebuilds without invalidating an older borrower");
  const auto count=frames.entries(),bytes=frames.bytes();rejected=false;try{frames.get(ToolbarRasterKey{1,1,true,2},[]()->ToolbarRasterSet{throw std::runtime_error("Owned raster failure");});}catch(...){rejected=true;}check(rejected&&frames.entries()==count&&frames.bytes()==bytes&&build(a)==fa,"Pixel generation failure preserves the preceding cache entries");
  rejected=false;try{frames.get(ToolbarRasterKey{1,1,true,2},[]{ToolbarRasterSet value;return value;});}catch(...){rejected=true;}check(rejected&&frames.entries()==count&&frames.bytes()==bytes,"An incomplete raster is rejected before cache mutation");auto retry=frames.get(ToolbarRasterKey{1,1,true,2},[]{return raster({1,1,true,2},88);});check(retry->pixels[11][2]==Bytes(4,88),"A failed raster entry can retry all twelve icons and three states");frames.clear();check(frames.entries()==0&&frames.bytes()==0&&fa->pixels[0][0].size()==16,"Clearing rasters releases retention and preserves immutable borrowers");
  ToolbarRasterCache budget(4,1152);auto f1=budget.get(a,[&]{return raster(a,1);});const ToolbarRasterKey narrow{1,2,false,0};budget.get(narrow,[&]{return raster(narrow,2);});budget.get(b,[&]{return raster(b,3);});check(budget.entries()==2&&budget.bytes()==864&&f1->pixels[0][0][0]==1,"Byte-budget eviction bounds retained memory independently of entry count");
  int oversized=0;for(const auto key:{ToolbarRasterKey{0,2,false,0},ToolbarRasterKey{-1,2,false,0},ToolbarRasterKey{1000000,1000000,false,0},ToolbarRasterKey{512,512,false,0}}){rejected=false;try{budget.get(key,[&]{++oversized;return ToolbarRasterSet{};});}catch(...){rejected=true;}check(rejected&&!budget.cacheable(key)&&oversized==0,"Unsupported raster sizes are rejected without invoking their builder");}
  for(int mode=0;mode<3;++mode){rejected=false;try{ToolbarRasterCache invalid(mode==0?0:mode==1?5:4,mode==2?ToolbarRasterCache::MaxBytes+1:ToolbarRasterCache::MaxBytes);}catch(...){rejected=true;}check(rejected,"Cache limits cannot exceed the fixed retention bounds");}
  ToolbarRasterCache bounded;for(uint64_t i=0;i<100;++i){ToolbarRasterKey key{2,2,false,i};bounded.get(key,[&]{return raster(key,(BYTE)i);});}check(bounded.entries()==4&&bounded.bytes()==2304,"Repeated generations retain only the four newest raster entries");
 }catch(const std::exception& failure){error=failure.what();}atomicText(root/L"results.json",Json{{"passed",error.empty()},{"checks",checks},{"error",error}}.dump(2),false);std::cout<<checks.size()<<" checks; "<<(error.empty()?"passed":error)<<"\n";return error.empty()?0:1;
}
